"""Private reference review; only the report is written to the agent workspace."""
import json
import os
from pathlib import Path

REPO = Path(os.environ.get("BENCH_REPO_ROOT", "/app/repo"))
APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPORT = json.loads("{\"schema_version\":2,\"reviews\":[{\"candidate\":\"cedar\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/cedar/seq.py\",\"line\":5},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"items\":[1,2,3]},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[1,2,3,4],\"k\":-1},\"expected\":{\"rotated\":[4,1,2,3],\"original\":[1,2,3,4]}},{\"input\":{\"items\":[1,2,3],\"k\":7},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[],\"k\":100},\"expected\":{\"rotated\":[],\"original\":[]}},{\"input\":{\"items\":[\"a\"],\"k\":-9},\"expected\":{\"rotated\":[\"a\"],\"original\":[\"a\"]}},{\"input\":{\"items\":[{\"x\":1},null,false],\"k\":0},\"expected\":{\"rotated\":[{\"x\":1},null,false],\"original\":[{\"x\":1},null,false]}}]},{\"candidate\":\"maple\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"items\":[1,2,3]},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[1,2,3,4],\"k\":-1},\"expected\":{\"rotated\":[4,1,2,3],\"original\":[1,2,3,4]}},{\"input\":{\"items\":[1,2,3],\"k\":7},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[],\"k\":100},\"expected\":{\"rotated\":[],\"original\":[]}},{\"input\":{\"items\":[\"a\"],\"k\":-9},\"expected\":{\"rotated\":[\"a\"],\"original\":[\"a\"]}},{\"input\":{\"items\":[{\"x\":1},null,false],\"k\":0},\"expected\":{\"rotated\":[{\"x\":1},null,false],\"original\":[{\"x\":1},null,false]}}]},{\"candidate\":\"birch\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"items\":[1,2,3]},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[1,2,3,4],\"k\":-1},\"expected\":{\"rotated\":[4,1,2,3],\"original\":[1,2,3,4]}},{\"input\":{\"items\":[1,2,3],\"k\":7},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[],\"k\":100},\"expected\":{\"rotated\":[],\"original\":[]}},{\"input\":{\"items\":[\"a\"],\"k\":-9},\"expected\":{\"rotated\":[\"a\"],\"original\":[\"a\"]}},{\"input\":{\"items\":[{\"x\":1},null,false],\"k\":0},\"expected\":{\"rotated\":[{\"x\":1},null,false],\"original\":[{\"x\":1},null,false]}}]},{\"candidate\":\"willow\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/willow/seq.py\",\"line\":5},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"items\":[1,2,3]},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[1,2,3,4],\"k\":-1},\"expected\":{\"rotated\":[4,1,2,3],\"original\":[1,2,3,4]}},{\"input\":{\"items\":[1,2,3],\"k\":7},\"expected\":{\"rotated\":[2,3,1],\"original\":[1,2,3]}},{\"input\":{\"items\":[],\"k\":100},\"expected\":{\"rotated\":[],\"original\":[]}},{\"input\":{\"items\":[\"a\"],\"k\":-9},\"expected\":{\"rotated\":[\"a\"],\"original\":[\"a\"]}},{\"input\":{\"items\":[{\"x\":1},null,false],\"k\":0},\"expected\":{\"rotated\":[{\"x\":1},null,false],\"original\":[{\"x\":1},null,false]}}]}]}")

def main():
    candidates = json.loads((REPO / "candidates.json").read_text())["candidates"]
    assert set(candidates) == {row["candidate"] for row in REPORT["reviews"]}
    APP.mkdir(parents=True, exist_ok=True)
    (APP / "review.json").write_text(json.dumps(REPORT, ensure_ascii=False, allow_nan=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()

